import{f as a,o as l,c as r,ah as e}from"./chunks/framework.5bt9HFMa.js";const c=JSON.parse('{"title":"操作系统存储管理","description":"","frontmatter":{},"headers":[],"relativePath":"series/操作系统/03-存储.md","filePath":"series/操作系统/03-存储.md","lastUpdated":1777791679000}'),n={name:"series/操作系统/03-存储.md"};function o(i,t,s,g,h,d){return l(),r("div",null,t[0]||(t[0]=[e('<h1 id="操作系统存储管理" tabindex="-1">操作系统存储管理 <a class="header-anchor" href="#操作系统存储管理" aria-label="Permalink to &quot;操作系统存储管理&quot;">​</a></h1><p>在现代操作系统中，存储管理（内存管理）是核心功能之一，主要负责内存的分配与回收、地址转换、内存扩充（虚拟内存）以及内存保护。</p><hr><h2 id="一、内存管理基础" tabindex="-1">一、内存管理基础 <a class="header-anchor" href="#一、内存管理基础" aria-label="Permalink to &quot;一、内存管理基础&quot;">​</a></h2><h3 id="_1-程序的装入与链接" tabindex="-1">1. 程序的装入与链接 <a class="header-anchor" href="#_1-程序的装入与链接" aria-label="Permalink to &quot;1. 程序的装入与链接&quot;">​</a></h3><p>为了让程序运行，必须将其装入内存。</p><ul><li><strong>编译</strong>：由编译程序将用户源代码编译成若干个目标模块。</li><li><strong>链接</strong>：由链接程序将目标模块和所需的库函数链接在一起，形成一个完整的装入模块。 <ul><li><strong>静态链接</strong>：运行前链接。</li><li><strong>装入时动态链接</strong>：装入内存时链接。</li><li><strong>运行时动态链接</strong>：运行时需要该模块才链接（便于共享）。</li></ul></li><li><strong>装入</strong>：由装入程序将装入模块装入内存运行。 <ul><li><strong>绝对装入</strong>：编译时产生绝对地址（单道程序）。</li><li><strong>可重定位装入（静态重定位）</strong>：装入时一次性完成地址转换。</li><li><strong>动态运行时装入（动态重定位）</strong>：运行时进行地址转换（需要重定位寄存器支持）。</li></ul></li></ul><h3 id="_2-逻辑地址与物理地址" tabindex="-1">2. 逻辑地址与物理地址 <a class="header-anchor" href="#_2-逻辑地址与物理地址" aria-label="Permalink to &quot;2. 逻辑地址与物理地址&quot;">​</a></h3><ul><li><strong>逻辑地址（相对地址）</strong>：CPU 生成的地址，用户程序中使用的地址。</li><li><strong>物理地址（绝对地址）</strong>：内存单元的真实地址。</li><li><strong>MMU（内存管理单元）</strong>：硬件机构，负责运行时将逻辑地址映射为物理地址。</li></ul><hr><h2 id="二、连续分配管理方式" tabindex="-1">二、连续分配管理方式 <a class="header-anchor" href="#二、连续分配管理方式" aria-label="Permalink to &quot;二、连续分配管理方式&quot;">​</a></h2><p>指为用户程序分配一个连续的内存空间。</p><h3 id="_1-单一连续分配" tabindex="-1">1. 单一连续分配 <a class="header-anchor" href="#_1-单一连续分配" aria-label="Permalink to &quot;1. 单一连续分配&quot;">​</a></h3><p>内存分为系统区和用户区，用户区仅驻留一道程序。无外部碎片，有内部碎片。</p><h3 id="_2-固定分区分配" tabindex="-1">2. 固定分区分配 <a class="header-anchor" href="#_2-固定分区分配" aria-label="Permalink to &quot;2. 固定分区分配&quot;">​</a></h3><p>将用户内存空间划分为若干个固定大小的分区。</p><ul><li><strong>分区大小相等</strong>：缺乏灵活性。</li><li><strong>分区大小不等</strong>：适应不同大小的程序。</li><li><strong>优缺点</strong>：无外部碎片，但有内部碎片（分区内未利用空间）。</li></ul><h3 id="_3-动态分区分配" tabindex="-1">3. 动态分区分配 <a class="header-anchor" href="#_3-动态分区分配" aria-label="Permalink to &quot;3. 动态分区分配&quot;">​</a></h3><p>不预先划分分区，根据进程大小动态建立。</p><ul><li><strong>数据结构</strong>：空闲分区表 / 空闲分区链。</li><li><strong>分配算法</strong>： <ul><li><strong>首次适应 (First Fit)</strong>: 地址递增，找第一个满足的。最快，保留了高址大空间。</li><li><strong>最佳适应 (Best Fit)</strong>: 容量递增，找最小能满足的。产生很多外部碎片。</li><li><strong>最坏适应 (Worst Fit)</strong>: 容量递减，找最大的。</li><li><strong>邻近适应 (Next Fit)</strong>: 从上次查找结束位置开始。</li></ul></li><li><strong>碎片问题</strong>：产生<strong>外部碎片</strong>（分区之间的小不可用空间），可通过**紧凑（Compaction）**技术解决。</li></ul><hr><h2 id="三、非连续分配管理-分页与分段" tabindex="-1">三、非连续分配管理：分页与分段 <a class="header-anchor" href="#三、非连续分配管理-分页与分段" aria-label="Permalink to &quot;三、非连续分配管理：分页与分段&quot;">​</a></h2><p>为了解决连续分配的碎片问题，引入了非连续分配。</p><h3 id="_1-分页管理-paging" tabindex="-1">1. 分页管理（Paging） <a class="header-anchor" href="#_1-分页管理-paging" aria-label="Permalink to &quot;1. 分页管理（Paging）&quot;">​</a></h3><h4 id="基本思想" tabindex="-1">基本思想 <a class="header-anchor" href="#基本思想" aria-label="Permalink to &quot;基本思想&quot;">​</a></h4><ul><li>将<strong>进程的虚拟地址空间</strong>和<strong>物理内存</strong>都划分为<strong>固定大小</strong>的块。 <ul><li>虚拟地址空间的块称为<strong>页（Page）</strong></li><li>物理内存的块称为<strong>页框（Page Frame）</strong> 或<strong>页帧</strong></li></ul></li><li>页与页框大小相同（通常为 4KB），便于映射。</li></ul><h4 id="地址结构" tabindex="-1">地址结构 <a class="header-anchor" href="#地址结构" aria-label="Permalink to &quot;地址结构&quot;">​</a></h4><p>虚拟地址 = <strong>页号（Page Number）</strong> + <strong>页内偏移（Offset）</strong></p><h4 id="页表" tabindex="-1">页表 <a class="header-anchor" href="#页表" aria-label="Permalink to &quot;页表&quot;">​</a></h4><ul><li>每个进程维护一张页表，记录“虚拟页 → 物理页框”的映射。</li><li><strong>快表 (TLB)</strong>：高速缓存，存放最近访问的页表项，加速地址变换。</li></ul><h4 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to &quot;优缺点&quot;">​</a></h4><ul><li><strong>优点</strong>：无外部碎片，内存利用率高。</li><li><strong>缺点</strong>：页表可能过大（需多级页表）；页面是物理单位，不反映逻辑结构。</li></ul><h3 id="_2-分段管理-segmentation" tabindex="-1">2. 分段管理（Segmentation） <a class="header-anchor" href="#_2-分段管理-segmentation" aria-label="Permalink to &quot;2. 分段管理（Segmentation）&quot;">​</a></h3><h4 id="基本思想-1" tabindex="-1">基本思想 <a class="header-anchor" href="#基本思想-1" aria-label="Permalink to &quot;基本思想&quot;">​</a></h4><ul><li>按<strong>逻辑意义</strong>将程序划分为若干<strong>段（Segment）</strong>（如代码段、数据段、栈）。</li><li>每段<strong>长度可变</strong>。</li></ul><h4 id="地址结构-1" tabindex="-1">地址结构 <a class="header-anchor" href="#地址结构-1" aria-label="Permalink to &quot;地址结构&quot;">​</a></h4><p>虚拟地址 = <strong>段号</strong> + <strong>段内偏移</strong></p><h4 id="优缺点-1" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点-1" aria-label="Permalink to &quot;优缺点&quot;">​</a></h4><ul><li><strong>优点</strong>：符合逻辑，便于共享（如共享代码库）和保护。</li><li><strong>缺点</strong>：产生外部碎片。</li></ul><h3 id="_3-段页式管理" tabindex="-1">3. 段页式管理 <a class="header-anchor" href="#_3-段页式管理" aria-label="Permalink to &quot;3. 段页式管理&quot;">​</a></h3><ul><li>先分段，段内再分页。</li><li>结合了分页的高效（无外部碎片）和分段的逻辑性（便于共享保护）。</li></ul><hr><h2 id="四、虚拟内存管理" tabindex="-1">四、虚拟内存管理 <a class="header-anchor" href="#四、虚拟内存管理" aria-label="Permalink to &quot;四、虚拟内存管理&quot;">​</a></h2><p>基于<strong>局部性原理</strong>，在程序装入时，只需将当前需要执行的部分页/段装入内存，其余留在外存，执行过程中动态调入/调出。</p><h3 id="_1-局部性原理" tabindex="-1">1. 局部性原理 <a class="header-anchor" href="#_1-局部性原理" aria-label="Permalink to &quot;1. 局部性原理&quot;">​</a></h3><ul><li><strong>时间局部性</strong>：某指令/数据被访问，不久后可能再次被访问（如循环）。</li><li><strong>空间局部性</strong>：某单元被访问，其附近单元可能被访问（如数组）。</li></ul><h3 id="_2-请求分页管理" tabindex="-1">2. 请求分页管理 <a class="header-anchor" href="#_2-请求分页管理" aria-label="Permalink to &quot;2. 请求分页管理&quot;">​</a></h3><p>在分页基础上增加了请求调页和页面置换功能。</p><ul><li><strong>页表项扩展</strong>：增加状态位（是否在内存）、访问字段、修改位、外存地址。</li><li><strong>缺页中断</strong>：访问的页不在内存时产生，属于内部异常。</li></ul><h3 id="_3-页面置换算法" tabindex="-1">3. 页面置换算法 <a class="header-anchor" href="#_3-页面置换算法" aria-label="Permalink to &quot;3. 页面置换算法&quot;">​</a></h3><p>当内存不足时，选择换出哪个页面。</p><table tabindex="0"><thead><tr><th style="text-align:left;">算法</th><th style="text-align:left;">名称</th><th style="text-align:left;">描述</th><th style="text-align:left;">特点</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>OPT</strong></td><td style="text-align:left;">最佳置换</td><td style="text-align:left;">淘汰以后永不使用或最长时间不使用的页面</td><td style="text-align:left;">理论最优，无法实现（需预知未来）。</td></tr><tr><td style="text-align:left;"><strong>FIFO</strong></td><td style="text-align:left;">先进先出</td><td style="text-align:left;">淘汰最早进入的页面</td><td style="text-align:left;">实现简单，但有<strong>Belady异常</strong>（物理块增加，缺页率反而上升）。</td></tr><tr><td style="text-align:left;"><strong>LRU</strong></td><td style="text-align:left;">最近最久未使用</td><td style="text-align:left;">淘汰最近最长时间未访问的页面</td><td style="text-align:left;">性能好，接近OPT。需硬件支持（栈/寄存器），开销大。</td></tr><tr><td style="text-align:left;"><strong>CLOCK</strong></td><td style="text-align:left;">时钟置换 (NRU)</td><td style="text-align:left;">循环扫描，检查访问位</td><td style="text-align:left;">性能接近LRU，开销较小。</td></tr></tbody></table><h3 id="_4-抖动-thrashing" tabindex="-1">4. 抖动 (Thrashing) <a class="header-anchor" href="#_4-抖动-thrashing" aria-label="Permalink to &quot;4. 抖动 (Thrashing)&quot;">​</a></h3><ul><li><strong>现象</strong>：刚换出的页马上又要换入，频繁调度，CPU利用率急剧下降。</li><li><strong>原因</strong>：分配给进程的物理块太少，不能满足工作集需求。</li><li><strong>工作集</strong>：在某段时间间隔内，进程实际访问的页面集合。</li></ul><hr><blockquote><p><strong>总结</strong></p><ul><li><strong>连续分配</strong>：简单，但有碎片。</li><li><strong>分页</strong>：物理视角，解决外部碎片，现代OS主流。</li><li><strong>分段</strong>：逻辑视角，便于共享保护。</li><li><strong>虚拟内存</strong>：逻辑扩充内存，核心是置换算法 (LRU)。</li></ul></blockquote>',56)]))}const b=a(n,[["render",o]]);export{c as __pageData,b as default};
